local quests = WordHunterWoW_QuestDataByFlavor.forever.deDE
quests[6] = { title = "Kopfgeld auf Garrick Padfoot", description = "Garrick Padfoot, ein Dieb und Halsabschneider, der schon seit Wochen unseren Bauern und Händlern das Leben schwer macht, ist bei einem Schuppen in der Nähe der Weinberge gesehen worden. Die Weinberge liegen im Osten der Abtei, auf der anderen Seite der Brücke. Bringt mir den Kopf des Schurken und verdient Euch das Kopfgeld, das auf ihn ausgesetzt ist!\n\nDoch seht Euch vor, $n. Garrick hat eine Bande von Rohlingen um sich versammelt, also werdet Ihr nicht leicht an ihn herankommen.", objectives = "Tötet Garrick Padfoot und bringt seinen Kopf zu Deputy Willem in der Nähe der Abtei von Nordhain.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "0928182aebd60cb2d0ee5de77dfce76fe0756423a1ad20b4f0780ced4ed3cf04" }
quests[7] = { title = "Säuberung im Koboldlager", description = "Eure erste Aufgabe ist eine Säuberung, $n. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", objectives = "Tötet 10 von dem Koboldgezücht und kehrt dann zu Marshal McBride zurück.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "97d0d0f2fd912fbbb87480c069ada50229bb3835b108201651799ca24b582eda" }
quests[15] = { title = "Überprüfung der Echokammmine", description = "Wie mir meine Späher mitteilen, ist das Koboldproblem größer als wir dachten, $n. Eine Gruppe Koboldtagelöhner hat ihr Lager in der Nähe der Echokammmine im Norden aufgeschlagen.\n\nBegebt Euch zu der Mine und entfernt die Kobolde. Wir wissen, dass sich mindestens 10 von ihnen dort aufhalten. Tötet sie, seht nach, ob dort noch mehr von ihnen sind, kommt dann zu mir zurück und erstattet Bericht.", objectives = "Tötet 10 Koboldtagelöhner und erstattet dann Marshal McBride Euren Bericht.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "ab7662542d88244f8df234b8f11c5f1088a520ee7dd6c806beef8af7a0a34584" }
quests[18] = { title = "Bruderschaft der Diebe", description = "Seit kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die \"Bruderschaft der Defias\" und sind auf der anderen Seite des Flusses im Osten gesehen worden.\n\nIch weiß nicht genau, was sie vorhaben, aber ich bin mir sicher, es ist nichts Gutes! Bringt mir die Kopftücher, die sie tragen, und ich werde Euch mit einer Waffe belohnen.", objectives = "Bringt 12 rote Sackleinenkopftücher zu Deputy Willem in der Nähe der Abtei von Nordhain.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "7491ce7d5aee647d6bc8330091cf07a38b3beb4c378e5fa91782231ebf651a27" }
quests[33] = { title = "Wölfe an der Grenze", description = "Ich hasse diese grässlichen Waldwölfe! Aber Wolfsteaks esse ich für mein Leben gern. Bringt mir zähes Wolfsfleisch, dann gebe ich Euch etwas dafür, das Euch von Nutzen sein wird.\n\nZähes Wolfsfleisch bekommt Ihr, wenn Ihr die Waldwölfe und jungen Wölfe jagt, die in Nordhain durch das Land streifen.", objectives = "Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "903338295b6e28e006014b440c65d4b7ef3a06ca26662145b88483229f540839" }
quests[176] = { title = "GESUCHT: \"Hogger\"", description = "Gesucht: Hogger\n\nEin riesiger Gnoll, Hogger, streunt im südwestlichen Elwynn durch den Wald. Er hat bislang alle Versuche, ihn zu fangen, vereiteln können.\n\nDie Armee von Stormwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt. Kopfgeldjäger, die sich die Belohnung verdienen möchten, sollten einen Beweis für Hoggers Tod bei Marshal Dughan in Goldhain vorlegen.", objectives = "Erschlagt den Gnoll Hogger und bringt seine gewaltige Gnoll-Klaue zu Marshal Dughan.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "2ae8e15bfb3a77ba9675196398828381166b33739f2047b765ae63cfee4fabf4" }
quests[287] = { title = "Höhle der Frostmane", description = "Ich bin mit meinem Bericht etwas im Rückstand und könnte Eure Hilfe brauchen, $n. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich habe so viele Trolle gesehen, dass ich mich nicht getraut habe, hineinzugehen.\n\nWas ich von Euch möchte, ist Folgendes: Geht runter zur Höhle, schaut Euch ein wenig darin um, tötet ein paar Trolle und kommt dann wieder hierher zurück.\n\nNehmt die Straße nach Norden, raus aus Kharanos. Sobald Ihr an der Brücke ankommt, folgt dem zugefrorenen Fluss westwärts, bis Ihr den Iceflowsee erreicht. Am linken Ufer werdet Ihr Brewnall vorfinden. Die Höhle liegt südwestlich des Dorfes.", objectives = "Erforscht die Höhle der Frostmane und tötet 5 Kopfjäger der Frostmane für Senir Whitebeard in Kharanos.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "247142bf29466b58bcc8d3f1d3fb0568639a4de0c8447b472ff5ca149a0a5847" }
quests[313] = { title = "Der altgediente Bau", description = "Nicht jeder ist dazu geschaffen, eine Belagerungsmaschine zu fahren. Dazu braucht man eine eiserne Hand und Nerven aus Stahl... zum Glück besitze ich beides! Wie steht's mit Euch? Wie groß ist euer Talent? Wollt Ihr es mir nicht zeigen?\n\nWie auch immer... ich versuche gerade, meine Maschine, Trollplow, etwas gemütlicher zu machen. Wie wäre es, wenn Ihr mir einen Haufen Wendigomähnen aus dem altgedienten Bau westlich von Kharanos besorgt? Diese Mähnen könnten einen tollen Teppich für das Innendeck abgeben!", objectives = "Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "e52e4fccc1a6102259abd74334875c25a89a60abd08ae8ae90a711eb4d6f0d69" }
quests[317] = { title = "Vorräte für Jetsteam", description = "Ich bereite mich gerade darauf vor, eine Mission für die Belagerungsbrigade in Angriff zu nehmen. Sie wird ziemlich lange dauern, und ich muss Jetsteam mit Vorräten für einen ganzen Monat beladen. Könntet Ihr also nicht, während Steelgrill an meinem Panzer arbeitet, ein wenig für mich auf die Jagd gehen?\n\nIch werde ein paar Pelze als Bettzeug und etwas Eberfleisch zum Essen brauchen. Ihr könnt das Fleisch von Ebern und die Pelze von Bären erbeuten... Ihr findet beide in den Schneefeldern südlich des altgedienten Baus.", objectives = "Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellowfiz in Steelgrills Depot ab.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "5ad6ea51f45c6affa729dce5d9c5d0b4600f30dae9ea014b2dd6ad0f851a673a" }
quests[384] = { title = "Eberrippchen in Biersauce", description = "Meine Tavernengäste mögen nichts so sehr wie meine Eberrippchen in Biersauce. Das einzige Problem dabei ist, dass der ortsansässige Fallensteller, der mich bisher mit den Zutaten versorgt hat, in die Armee des Königs eingetreten ist, um im Krieg an der Allianzfront zu helfen. \n\nVielleicht könnt Ihr mir helfen? Wenn Ihr mir sechs Klippeneberrippchen bringt und ein Rhapsody-Malzbier von der Taverne hier besorgt, bekommt Ihr das Familienrezept für meine berühmten Eberrippchen in Biersauce, und nicht zu vergessen natürlich eine Kostprobe! Das Geheimnis liegt im Malz!", objectives = "Ragnar Donnerbräu in Kharanos benötigt 6 Klippeneberrippchen und einen Krug Rhapsody-Malzbier.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "e5464e22ce034c8215fa733b5cf577d24ed5bc1b8b4f664a2c11f9b781e19b08" }
quests[400] = { title = "Werkzeuge für Steelgrill", description = "Beldin Steelgrill ist der Besitzer der örtlichen Maschinenschlosserei, und er ist der beste Monteur von Belagerungsmaschinen, den es gibt! Allerdings geht er nicht sehr gnädig mit seinen Werkzeugen um. Ich schwöre Euch, er macht bald mehr Bogenlichtschraubenschlüssel kaputt, als wir ihm liefern können!\n\nWir haben gerade seine letzte Werkzeugbestellung fertig. Wenn Ihr sie ihm anliefert, wird er sich sicherlich erkenntlich zeigen.\n\nSein Geschäft, Steelgrills Depot, liegt etwas nordöstlich von Kharanos. Und nebenbei, es handelt sich dort um einen örtlichen Treffpunkt für die Veteranen unter den Piloten der Belagerungsmaschinen, also hört Euch ruhig ein wenig um, während Ihr dort seid.", objectives = "Liefert Beldin Steelgrill seine Werkzeuge.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "00ecbfae6fb87d620281419760395da4f004277ef0b5290cd41d1dbfa6e0da0e" }
quests[483] = { title = "Die Relikte des Erwachens", description = "Eindringlinge der Knarzklauen wurden beim Überfall im Westen des Ban'ethil-Grabhügels gesehen.\n\nWenn wir ihnen nicht zur Hilfe kommen, werden die schlummernden Druiden auf ewig im Smaragdgrünen Traum gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert. Das empfindliche Ritual des Großen Schlafes kann ohne die Relikte des Erwachens nicht unterbrochen werden.\n\nReist zum Höhlenbau und bringt den Rabenkrallentalisman, den schwarzen Federkiel, den Saphir des Himmels sowie die Rune des Nistens herbei. Die Druiden bewahren sie in heiligen Truhen auf. Bringt sie zu mir, damit ich das Weck-Ritual vorbereiten kann.", objectives = "Bringt die Relikte des Erwachens zu Athridas Bearmantle nach Dolanaar.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "db17e886802d90005a96309051fd18647331c2bf9cead6af1034944ab8f138fe" }
quests[486] = { title = "Ursal der Raufer", description = "Jetzt ist die Zeit gekommen, die Druiden der Kralle zu retten. $n, sollten wir jetzt versagen, sind sie für immer im Schlaf verloren.\n\nIch werde die Relikte des Erwachens vorbereiten und das Ritual durchführen. Damit meine Arbeit Wirkung zeigen kann, muss die verfluchte Bestie, die für diese schreckliche Situation verantwortlich ist, getötet werden. Erst dann ist das Ritual vollkommen.\n\nEs war Ursal der Raufer, der sich in die Berufung unserer Brüder eingemischt hat, und er ist es auch, der nun bezahlen muss, damit sie befreit werden können. Begebt Euch nach Südwesten zur Höhle der Knarzklauen und erschlagt ihn.", objectives = "Tötet Ursal den Raufer und kehrt zu Athridas Bearmantle nach Dolanaar zurück.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "fb48cbe90426e94d9f42a9ad827e26ee9a8a07adebd3100cf8615c512e7cf2d8" }
quests[487] = { title = "Die Straße nach Darnassus", description = "Die Straße nach Darnassus muss sicher bleiben. Reisende, die von Dolanaar nach Darnassus fuhren, haben von ruchlosen Angriffen der verderbten Furbolgs des Knarzklauenstammes berichtet.\n\nJeden Tag gelangen auf diesem Weg wichtige Nachrichten und auch Waren von und nach Darnassus. Es darf einfach nicht sein, dass eine schurkische Bande von Heiden alle terrorisiert.\n\n$C, bewaffnet Euch im Namen des Heiligen Waldes. Ihr Bau liegt irgendwo unterhalb dieser Position. Erschlagt 6 Wegelagerer der Knarzklauen und berichtet mir dann.", objectives = "Erschlagt 6 Wegelagerer der Knarzklauen und kehrt zu Schildwache Amara Nightwalker außerhalb Dolanaars zurück.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "7cc121c8c3bc4e722e68dabbacc4e7861bfb6eb37c14340f4e41f3c5ad7f7e1e" }
quests[783] = { title = "Die Bedrohung von innen", description = "Ich hoffe, Ihr habt Euren Gürtel festgezurrt, $C, denn es gibt hier in Nordhain viel Arbeit.\n\nUnd ich meine damit nicht Landarbeit.\n\nDie Wachen von Stormwind haben alle Hände voll zu tun, um den Frieden zu bewahren; viele von uns weilen in fernen Ländern und viele Bedrohungen rücken immer näher. Deshalb rekrutieren wir jeden, der gewillt ist, seine Heimat zu verteidigen. Und die Allianz.\n\nFalls Ihr hier seid, um dem Aufruf zu folgen, sprecht mit meinem Vorgesetzten, Marshal McBride. Er ist in der Abtei hinter mir.", objectives = "Sprecht mit Marshal McBride.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "e757802037090ff50dcdea346eeea97001b994b4491c2df6314abae7d26dc3a7" }
quests[922] = { title = "Rellian Greenspyre", description = "$n, würdet Ihr wohl eines der Samenkörner, die Ihr mir besorgt habt, meinem Freund Rellian Greenspyre bringen? Er ist Druide in Darnassus, und bei unserem letzten Gespräch machte er deutlich, dass er an meiner Arbeit mit den Bäumlingen interessiert sei. Er hatte selbst ein paar Ideen und würde sich über ein Exemplar dieser Samenkörner sicherlich freuen.\n\nDanke, $n. Ihr wart mir eine große Hilfe. Ich hoffe, dass ich Euch eines Tages die Früchte meiner Arbeit zeigen kann.\n\nIhr findet Rellian normalerweise die Wege der Enklave des Cenarius in Darnassus entlangwandernd.", objectives = "Bringt Rellian Greenspyre in Darnassus ein Bäumlingssamenkorn.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "68b9180dedf15f3c38123cf6eaea4eaf7416d6e32c7b577075afcacb4b3fd339" }
quests[923] = { title = "Tumore", description = "Bosheit wuchert in den Bäumlingen. Wir versuchen, die Ursache dafür zu finden, aber bis dahin... Aus Sorge um Teldrassils Sicherheit müssen wir alle Bäumlinge fällen, denen nicht mehr geholfen werden kann. Diejenigen, die die Gegend um den Wellspringsee im Norden von Teldrassil durchstreifen, sind am schlimmsten betroffen. Sie müssen ausgemerzt werden!\n\nVernichtet alle Bäumlinge, die Ihr dort findet, und sammelt die moosartigen Tumore, die auf ihnen wachsen. Bringt mir die Tumore, damit ich sie verbrennen kann.", objectives = "Bringt Rellian Greenspyre in Darnassus 5 moosartige Tumore.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "a51616a63179311e61127276fece15297a2ae50e8e82aafaa8809019660a503b" }
quests[927] = { title = "Das moosumschlungene Herz", description = "Das Herz von Schwarzmoos dem Stinker ist mit einem dunklen, öligen Moos bedeckt. Dass es sich wirklich um ein Herz handelt, kann man eigentlich nur daran erkennen, dass es langsam und rhythmisch schlägt... Ein Herzschlag, der sogar jetzt noch anhält.\n\nVielleicht würde Denalan dieses Herz gern einmal sehen.", objectives = "Bringt Denalan am Al'Amethsee das moosumschlungene Herz.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "0fb893e59d66e7278ec86f25854903b7676ded4802dcdca16a0241044950cf1a" }
quests[930] = { title = "Die leuchtende Frucht", description = "Unter den Wedeln dieser leuchtenden Pflanze befindet sich eine große, runde Frucht.\n\nDenalan würde diese Frucht bestimmt gern studieren, da seid Ihr Euch sicher.", objectives = "Bringt Denalan am Al'Amethsee die leuchtende Frucht.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "212d2cca806a37501c7814cae6384603227472c1e7f86b5fa2cc7c483b24029f" }
quests[933] = { title = "Krone der Erde", description = "Südöstlich des Ortseinganges von Darnassus, an den Ufern der Teiche von Arlithrien, gibt es noch einen Mondbrunnen. Die Schildwachen können aufgrund von Angriffen und der ständig schlimmer werdenden Hinterhältigkeit der Knarzklauenfurbolgs kaum durch dieses Gebiet patrouillieren.\n\nSeid auf der Hut, wenn Ihr Euch dem Brunnen nähert, und haltet Eure Waffen stets griffbereit.", objectives = "Füllt die Turmalinphiole und bringt sie Corithras Moonrage in Dolanaar.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "06f6efa457d40bb6263e6fcd31c039f5a1b0aae2a1dff76e8885a1b4fcbba723" }
quests[937] = { title = "Die verzauberte Lichtung", description = "Man hat mich mit einer kleinen Gruppe Schildwachen hierher beordert, um den Orakelbaum vor den Harpyien zu beschützen, die überall im Tal Nester gebaut haben. Wir versuchen, sie langsam aber sicher zurückzudrängen.\n\nBeim Versuch des Orakelbaums, einen Läufer mit einem Bericht nach Darnassus zu entsenden, wurde dieser von einer Gruppe eben jener Harpyien angegriffen und getötet.\n\nWenn Ihr glaubt, dieser Aufgabe gewachsen zu sein, begebt Euch zu ihren Nestern, erschlagt sie und bringt mir zum Beweis Eurer Taten deren Gürtel.", objectives = "Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Cloudsbreak in der Lichtung des Orakels.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "f29c0cc4fd648104783442f5a1e675a81ae11a300eefd3cce5598cc692a604ed" }
quests[952] = { title = "Der Hain der Uralten", description = "Wenn Ihr genug Zeit hattet, um für den Orakelbaum Nachrichten zu übermitteln, kann ich Euch sicherlich dazu bewegen, eine Nachricht in den Hain der Uralten in Dunkelküste zu bringen, südlich von Auberdine.\n\nIhr werdet höchstwahrscheinlich ein sicheres Transportmittel wie einen Hippogryphen benötigen, aber ich baue darauf, dass Ihr das regeln könnt. Bringt dies Onu, dem Urtum der Lehren. Er wartet auf eine Nachricht von mir, so wie ich auf Neuigkeiten aus der Lichtung des Orakels wartete.", objectives = "Bringt Fandrals Nachricht zu Onu in den Hain der Uralten in Dunkelküste, südlich von Auberdine.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "f7f413bf6a90852ff1ba128d35b3382b3b4597223458bf246c047af7bdef9a6f" }
quests[1683] = { title = "Vorlus Elendshuf", description = "Bevor ich Euch unterrichten kann, müsst Ihr mir Eure Entschlossenheit beweisen.\n\nDer Satyr Vorlus Elendshuf hat einen unserer entlegenen Mondbrunnen südöstlich der Grabhügel von Ban'ethil gefunden. Nun planscht er darin und verseucht das reine Wasser mit seinem Schmutz.\n\nSucht Vorlus beim Mondbrunnen und vernichtet ihn. Bringt mir sein Horn als Beweis, dann beginne ich Eure Fortgeschrittenen-Ausbildung zum Krieger.\n\nDer Weg zum Mondbrunnen ist gut verborgen, $n, doch wenn Ihr konzentriert und wachsam bleibt, werdet Ihr ihn finden.", objectives = "Bringt das Horn von Vorlus zu Elanaria in Darnassus.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "88e1c343ed77949db9c9268259037b8afb83ff80ba2c2b918579b0db7d3b463a" }
quests[1684] = { title = "Elanaria", description = "Seid gegrüßt, Krieger. Eure Fertigkeiten wachsen, doch Eurer Beruf verlangt mehr, als Ihr für möglich haltet. Um weiter zu kommen müsst Ihr bald einen Lehrer finden.\n\nDie Kriegerin Elanaria weilt in Darnassus auf der Terrasse der Krieger. Sie kann Euch unterweisen.", objectives = "Sprecht mit Elanaria.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "5bf0d76f2c003d3f83f79e7e366c568f58242046878ee05e6241964f51a00aa2" }
quests[2241] = { title = "Der Apfel fällt", description = "Sie sagen, ich bin 'liebeskrank', was immer das heißen mag.\n\nKlar, ich denke ununterbrochen an Syurna. Klar, mein Haus ist voll von Bildern und Zeichnungen von Syurna. Klar, es kommt vor, dass ich tagelang nicht esse, schlafe oder trinke, während ich über die Liebe lamentiere, die uns nicht zuteil wurde. Ist das so falsch?\n\nJetzt will sie mich nicht sehen! MICH! Ich habe versucht, ihr Nachrichten zu schicken, aber sie redet mit keinem, es sei denn, er wäre ein Schurke.\n\nKönntet Ihr diese Blume zu ihr bringen? Und vergesst nicht, ihr zu sagen, dass sie von Jannok ist.", objectives = "Bringt Jannoks Rose zu Syurna in Darnassus.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "2926b88abe4683cc98f465a8845bd5911315f096c71826ca00bbfe2f18557992" }
quests[2242] = { title = "Das Schicksal ruft", description = "Wir glauben, dass es ein Wesen gibt, das uns verstehen helfen könnte, was mit den Wäldern von Teldrassil geschieht. Leider hatte es verheerende Folgen, als wir versuchten, dieses Wesen zur Mitarbeit zu überreden.\n\nEr versteckt sich auf einem Ast am Rand der Lichtung des Orakels. Alle, die sich dem Satyr bisher genähert haben, sei es mit Gewalt oder Diplomatie, fanden ein böses Ende. Vielleicht ist Verstohlenheit die Lösung, $n.\n\nFindet heraus, was Sethir der Uralte in seinen Rucksäcken hat und berichtet mir davon.", objectives = "Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "e97c37797a1a61eecbe713393443dc78833db6802c4936c1ffd200391040d2ad" }
quests[2498] = { title = "Rückkehr zu Denalan", description = "Ich habe gerade erfahren, dass Denalan am Al'Amethsee herausgefunden hat, was der Grund für die Tumore sein könnte, von denen die Bäumlinge befallen sind. Bitte sprecht mit ihm und sagt ihm, dass ich Euch geschickt habe.\n\nSputet Euch, $n; er braucht unsere Hilfe.", objectives = "Rellian Greenspyre möchte, dass Ihr am Al'Amethsee mit Denalan sprecht.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "60d2904972862394790ed3a0a62a091caceb8f0c716107e45406874a6d8dca03" }
quests[2499] = { title = "Grimmeiche", description = "In einer Höhle am Südufer des Sees überträgt ein Bäumling namens Grimmeiche die Verderbnis auf alle Wesen, die am Al'Amethsee leben.\n\nIch habe mich nicht allzu nah herangewagt, aber selbst aus der Entfernung ist eines ganz klar: Grimmeiche wird von dem größten Tumor vergiftet, den ich je gesehen habe. Ich würde sogar sagen, er ist nicht nur groß, er ist riesengroß.\n\nIhr habt schon viel getan, um mir zu helfen, $n, und doch möchte ich Euch um einen weiteren Gefallen bitten. Spürt Grimmeiche auf und holt den Tumor. Entfernt diese Quelle der Verderbnis aus meiner Heimat!", objectives = "Denalan vom Al'Amethsee möchte, dass Ihr den riesengroßen Tumor von Grimmeiche einsammelt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "5c17083d4fef19eac8b422a2e5bb4a39dfd44508d8943e74cd1038d64da995ae" }
quests[2518] = { title = "Tränen des Mondes", description = "Einst wurde Lady Sathrah von Elune geliebt. Grazil und rein spann die Spinne ihre silbernen Fäden im Mondlicht, wo sie den Abendnebel einfingen. Der silbrige Tau hatte starke Heilkräfte und wurde darum hier im Tempel aufbewahrt.\n\nDoch in jüngster Zeit ist Sathrah dem Wahnsinn verfallen. Auch die ihr nachfolgenden Generationen sind nun gefährdet.\n\nFindet Lady Sathrah, $n, und beendet ihr Leiden. Sie hält sich an der nördlichen Grenze von Teldrassil auf, in der Nähe des Wellspringsees. Sammelt ihre silbrigen Spinndrüsen und bringt sie mir.", objectives = "Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "525410429dfcc9a398c76cc84bdf3728575e5383949eba9f56307de5a0d46849" }
quests[2519] = { title = "Der Tempel des Mondes", description = "Ein einstmals großes Wesen des Waldes benötigt Hilfe, $R.\n\nEine schwierige Aufgabe muss getan werden.\n\nBitte sucht Priesterin A'moora auf: Sie wird Euch alles erklären. Ihr findet sie südöstlich von hier im Tempel des Mondes.", objectives = "Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "149d632340246204bb5effc8b1f40b7bbe732f97063497789067b89c8df608ab" }
quests[2541] = { title = "Der schlafende Druide", description = "Die hier lebenden Schamanen der Knarzklauen haben einen Weg entdeckt, wie man den Geist eines schlafenden Druiden von seinem Körper trennen kann. Die Furbolgs haben meinen physischen Körper reanimiert und lassen ihn jeden angreifen, der versucht, den Grabhügel von Ban'ethil zu erforschen. Ich selbst bin im Smaragdgrünen Traum gefangen und kann diesem Treiben keinen Einhalt gebieten.\n\nIhr müsst mir helfen. Die Knarzklauenschamanen tragen einen seltsamen Glücksbringer bei sich, mit dem dieses Ritual durchgeführt wird, und ich würde einen solchen Glücksbringer gern untersuchen. Bitte, $n, bringt mir einen.", objectives = "Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "2f617f859d9698539d0016a03c8d2fa224e4fd2be485d287a95743c5537ecc14" }
quests[2561] = { title = "Druide der Klaue", description = "Nachdem ich den Glücksbringer untersucht habe, weiß ich jetzt, was zu tun ist, $n. Bitte nehmt ihn, und tut das, worum ich Euch bitte.\n\nIhr müsst die tiefsten Tiefen des Grabhügels von Ban'ethil erforschen. Dort findet Ihr meinen seelenlosen Körper. Und obwohl es mich sehr schmerzt, Euch das jetzt zu sagen, sehe ich keine andere Möglichkeit, wie ich mich der Kontrolle der Knarzklauen entziehen kann.\n\nDamit ich mich von ihnen befreien kann, müsst Ihr meinen physischen Körper töten. Sobald das getan ist, wendet den Voodooglücksbringer auf meinen gefallenen Körper an. Und wenn Ihr diese Aufgabe erfüllt habt, kommt zu mir zurück.", objectives = "Oben Zornklaue möchte, dass Ihr seinen seelenlosen Körper tötet und dann den Voodooglücksbringer anwendet.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "e250a1d2654508a8ba2d5f2400c34059c0b00c8d3842558474745649fb99c980" }
quests[3905] = { title = "Traubenliste", description = "Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.\n\nIhr findet Bruder Neals im Glockenturm der Abtei... wo er gern seinen Wein probiert.", objectives = "Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "50fa15c91c9a35a14b86c0c7718e9becdfbc7652a1c906a0b2ff4f6d55151b0c" }
quests[5261] = { title = "Eagan Peltskinner", description = "Eagan Peltskinner sucht nach jemandem, der für ihn Wölfe jagt. Das ist gut, da wir es hier im Nordhaintal in letzter Zeit verstärkt mit Wölfen zu tun haben.\n\nWenn Ihr interessiert seid, dann sprecht mit Eagan. Ihr findet ihn neben der Abtei, auf der linken Seite.", objectives = "Sprecht mit Eagan Peltskinner.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "1acf89168e4b92574e2252ffc887d9bb5d569d241035adf8912eccec440b3d13" }
quests[5625] = { title = "Gewänder des Lichts", description = "Normalerweise wird etwa zu dieser Zeit die Macht in einem von Euch geprüft, um zu sehen, ob er würdig genug ist, jene Roben zu tragen, die seinen Platz in der Kirche anzeigen. Doch um ehrlich zu sein, gibt es wichtigere Dinge, um die ich mich kümmern muss. Bürger von Kharanos kamen gerade hierher und erzählten mir von einem verletzten Gebirgsjäger direkt außerhalb der Stadt im Süden - sein Name ist Dolf.\n\nWenn Ihr Dolf heilt und ihm 'Seelenstärke' gebt, werde ich das als erfolgreiche Prüfung ansehen. Wie klingt das?", objectives = "Sucht den Gebirgsjäger Dolf und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "979c704764fa30ef425cde40e06a7f5a47a2d9207087745f3b14a47f21ede866" }
quests[5627] = { title = "Sterne von Elune", description = "", objectives = "", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "324721b1524d4bb99beb438305ccbe603fc6a75e9bd85abb7f1a16da466588a4" }
quests[5676] = { title = "Arkane Rückkopplung", description = "", objectives = "", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "b13374fde91c9eff2a791ceface45b315c1645d0d4f7cf07cb185f407de169bc" }
quests[6071] = { title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Dazalar in Dolanaar.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "6379d1a6b36de0e3dd1b19c47d8b287aa36d7ad4e85d00dc8354b313cee3c1b3" }
quests[6073] = { title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Dazalar in Dolanaar.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "acb964514cba89c65e6fc501d45b033c7442261cea8689da9791aa255c765632" }
quests[6341] = { title = "Die Arten von Teldrassil", description = "Den Anglern des Dorfes Rut'theran geht es sehr gut, denn die Fische dort sind extrem groß und zahlreich. Ich würde die hier vorkommenden Arten gern mit denen des Festlandes vergleichen.\n\nIch habe eine Sammlung von Fischgräten und Schuppen, die ich gern zu einem Kollegen von mir in Dunkelküste bringen würde. Er heißt Laird und ist ein Fischverkäufer im Dorf Auberdine.\n\nBringt meine Sammlung zu unserem Hippogryphenmeister Vesprystus und besprecht mit ihm, wie Ihr am besten nach Auberdine kommt.", objectives = "Bringt Nessas Sammlung zu Vesprystus.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "e29928b8d2552babf3202006bd1f4bf064df94ce91340c428e06f848d1cdacd6" }
quests[6344] = { title = "Nessa Shadowsong", description = "Eine Freundin von mir, Nessa Shadowsong, ist Anglerbedarfshändlerin in Rut'theran. Sie muss ein Päckchen nach Dunkelküste bringen und sucht jemanden, der ihr hilft.\n\nWenn Ihr zu Nessa wollt, dann müsst Ihr in Darnassus das Portal nach Rut'theran benutzen. Ihr findet das Portal westlich der Tempelgärten.", objectives = "Sprecht mit Nessa Shadowsong.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "2457af359b829bdfa41ff740fdd88cca1c3d64b9e65bceb3142df22cc149539d" }
quests[7383] = { title = "Krone der Erde", description = "Mit Teldrassil stand es jedoch nicht zum Besten. Staghelms sorgfältig durchdachte Pläne für den neuen Weltbaum entwickelten sich nicht so, wie er gehofft hatte, denn es gab ein kleines Problem. Ein Problem, das die Ursache für viele weitere Probleme Teldrassils ist.\n\nWie dem auch sei, dazu komme ich später. Ihr müsst den letzten Mondbrunnen nordwestlich von hier in der Lichtung des Orakels aufsuchen. Unter den Ästen des Orakelbaums befindet sich der wichtigste und mächtigste unserer Brunnen. Beschafft eine Phiole seines Wassers und bringt sie mir.", objectives = "Füllt die Amethystphiole und bringt sie Corithras Moonrage in Dolanaar.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "0640c4abc4dd455ec79900d2f8ab6f1e825bde472add6c50a2606e3f7938fbca" }
quests[87288] = { title = "Weiche Säblerpelze", description = "Hallo $uReisender:Reisende;! Ich hoffe, Ihr genießt Euren Besuch in unserem Dorf. Ich mag Dolanaar; es ist klein, charmant und alle sind freundlich.\r\n\r\nIch bin ein örtlicher Händler und habe allerlei Werkzeuge und Schmuckstücke im Angebot, die Euch auf Euren Reisen von Nutzen sein könnten. Tatsächlich kann ich Euch einen Tauschhandel anbieten, falls Ihr interessiert seid! Ich benötige einige Nachtsäblerpelze. Diese majestätischen Kreaturen sind wunderschön, doch in dieser Gegend auch recht aggressiv. Ihr könnt es also als Selbstverteidigung verbuchen.", objectives = "Bringt Aldria $1oa weiche Nachtsäblerpelze.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "2a4780b4137d645dae154c622260acd644aa2ed5150d60385d85eb13aeccfe3b" }
quests[91741] = { title = "Angeknabbertes Buch", description = "<Einer der Kobolde hat dieses Buch fallen lassen. Es scheint so, als hätte der Kobold versucht, es zu essen.\r\n\r\nBruder Paxton kümmert sich in der Abtei um eine kleine Bibliothek. Von dort muss das Buch stammen.>", objectives = "Bringt das Buch zu Bruder Paxton zurück.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "82cb58f0c258f7c6dae66cfd196a96e34600d57cf09fff88cc00534688948cf5" }
quests[91745] = { title = "Bergbauberater", description = "Sprecht mit dem neuen Bergbaulehrling Kelsey Fargo. Sie arbeitet direkt außerhalb der Mine und hat höchstwahrscheinlich gesehen, was die Kobolde treiben. Vielleicht kann sie Euch dabei gleich das ein oder andere über den Bergbau beibringen.", objectives = "Sprecht mit Kelsey Fargo außerhalb der Echokammmine im Nordhaintal.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "1b107267f1f4e50841fcec2ec3c72273e4915407e8e4b5b54c34211ed5e16bf0" }
quests[91758] = { title = "Folgt diesem Kobold!", description = "Ihr seid mit diesen Kobolden noch nicht fertig. Wir haben gerade von Kelsey erfahren, dass ein Kobold die Mine mit einem großen Sack voller Bücher verlassen hat. Ich möchte, dass Ihr diesen Kobold ausfindig macht, damit wir die Bücher für Bruder Paxton zurückholen können.\r\n\r\nSprecht mit Tordrin Sternblade. Er ist der neue Jägerlehrer, der gerade erst aus Ironforge eingetroffen ist. Ihr findet ihn hinter der Abtei, in der Nähe des Stalls. Er kann Euch helfen, diesen Kobolddieb ausfindig zu machen.", objectives = "Sprecht mit Tordrin Sternblade in der Nähe des Stalls hinter der Abtei von Nordhain.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "1468889ce931a24d646349ff8eb69911599f741fce4fa459fcede66d53c1e761" }
quests[91777] = { title = "Seltene Bücher", description = "Es fehlen nur noch zwei Bücher von Bruder Paxtons Liste: \"Geomantie für neugierige kleine Zauberer\" und \"Arkane Erläuterungen: Magisches in einfachen Worten\".\r\n\r\nDie Kobolde müssen sie zur Jaspismine gebracht haben. Bitte findet diese zwei Bücher und bringt sie zu Bruder Paxton zurück.\r\n\r\nAber ich befürchte, dass es ziemlich gefährlich sein wird. Wenn der \"Koboldlehrling\" einen Elementar beschwören kann, will ich mir gar nicht ausmalen, wozu der Meister imstande ist. Ich an Eurer Stelle würde ein paar Freunde mitbringen.", objectives = "Findet \"Geomantie für neugierige kleine Zauberer\" und \"Arkane Erläuterungen: Magisches in einfachen Worten\" und bringt sie zu Bruder Paxton in der Abtei von Nordhain zurück.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "c85873e6ef71515815b7b2ce53f2288a9090b10c94fb1f6ea41ead6c2b174a72" }
quests[92124] = { title = "Bücherliste", description = "Wir müssen herausfinden, wie viele Bücher fehlen!\r\n\r\nSprecht mit meinem nutzlosen Assistenten Daniel. Er kann eine schnelle Bestandsaufnahme machen und herausfinden, wie gravierend das Problem ist.\r\n\r\nEr ist besessen von den verschiedenen Handelsberufen im Wald von Elwynn. Der Junge konzentriert sich lieber darauf, anstatt mir zu helfen.\r\n\r\nWürgt ihn ab, wenn er anfängt, von Berufsfertigkeiten zu schwadronieren, und findet heraus, was mit meinen Büchern geschehen ist!", objectives = "Sprecht in der Bibliothek mit Daniel, Bruder Paxtons Gehilfe.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "feb572b508310f240410528005b91a2ebf668c597ec31a52442b514cd6b99705" }
quests[93963] = { title = "Erkundung der Allianz", description = "Stormwind, Ironforge und Darnassus unterscheiden sich alle durch ihre ganz eigenen Bewohner und ihre einzigartige Kultur. Als Gast der Allianz hier auf Azeroth empfiehlt es sich, jede unserer Hauptstädte zu besuchen.\r\n\r\nSprecht mit Randal Emerson im südlichen Vorraum, um Hinweise für Euer Unterfangen zu erhalten.", objectives = "Sprecht mit Randal Emerson in der Burg Stomwind, um weitere Hinweise zu erhalten. Nutzt die erhaltenen Hinweise, um König Magni Bronzebeard, Hochtüftler Mekkatorque und Tyrande Whisperwind aufzusuchen und mit ihnen zu sprechen.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "bc9da39aee96e5cbfa0d8f5556478d3f14b92fbfcdcc1a7796d6e42e3893b407" }
quests[96055] = { title = "Grundlagen des Zeltens: Kräuterkunde", description = "Sieht aus, als hättet Ihr Euch etwas Wissen in Kräuterkunde angeeignet. Blumen pflücken ist nicht bloß ein Zeitvertreib, es kann auch sehr nützlich sein... und profitabel.\r\n\r\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Räucherkerze für Euer Lager herstellen könnt. Gute Laune ist wichtig, um Heiler und Zauberwirker bei der Stange zu halten, und eine Räucherkerze kann allen, die Magie einsetzen, einen Schub geben.", objectives = "Geht nach Ironforge und sprecht mit Reyna Stonebranch, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "0b19f40b09f850ca371e1e50e4aa6eaa9dc8f35082a61fdb0b1d5ffd2fc89cc5" }
quests[96057] = { title = "Grundlagen des Zeltens: Schneiderei", description = "Die Schneiderei ist eine überraschend effektive Handwerkskunst, und ich bin sicher, sie wird Euch einigen Nutzen bringen.\r\n\r\nIch kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fraktionsbanner für Euer Lager anfertigt, sofern Ihr die Fertigkeit dazu habt. Motivation und Kampfmoral sind enorm wichtig für den Erfolg auf dem Schlachtfeld, und ein inspirierendes Banner sorgt dafür, dass Ihr mit vollem Einsatz bei der Sache bleibt.", objectives = "Geht nach Ironforge und sprecht mit Urthar Threx, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "2895903e8d082fe421de551e2b9a387c91de97f448ce7b4d392ce7dbf3dd7563" }
quests[96059] = { title = "Grundlagen des Zeltens: Verzauberkunst", description = "Jetzt, wo Ihr in die Verzauberkunst eingestiegen seid, kann ich Euch beibringen, wie Ihr eine verzauberte Laute für Euer Lager herstellen könnt, sobald Ihr ein paar Kenntnisse habt.\r\n\r\nUnterhaltung in der Freizeit ist immer wichtig, und dieses bisschen Magie kann Euch dabei helfen, Euch auf die verschiedensten Herausforderungen vorzubereiten, wenn Ihr Euch wieder auf den Weg macht, so staubig er auch sein möge.", objectives = "Geht nach Ironforge und sprecht mit Thonys Pillarstone, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "9364dc8c04d473435c14df30daebcf0b28687eb00300e41ec88773e285b703cb" }
quests[96606] = { title = "Die große weite Welt", description = "Seid gegrüßt, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Das ist gut. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\r\n\r\nIhr werdet lernen müssen, Euch in der Wildnis wohlzufühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\r\n\r\nSetzt Euch neben das Feuer und macht es Euch gemütlich. Ich werde Euch alles erklären.", objectives = "Setzt Euch an Lyreenas einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "ed2abde9ff692b85aed80a6d129f07fc2f70cb628ab1190ab5ba4af20576acf6" }
quests[96608] = { title = "Die große weite Welt", description = "Seid gegrüßt, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Das ist gut. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\r\n\r\nIhr werdet lernen müssen, Euch in der Wildnis wohlzufühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\r\n\r\nSetzt Euch neben das Feuer und macht es Euch gemütlich. Ich werde Euch alles erklären.", objectives = "Setzt Euch an Erics einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "0c601487c5b605660be63241bd9b9faa3a37fbf5ed03c5295baa4f084df85f21" }
quests[97943] = { title = "Grundlagen des Zeltens: Angeln", description = "Ob Ihr es glaubt oder nicht, Eure Fähigkeiten als $gAngler:Anglerin; können für Euer Lager durchaus nützlich sein.\r\n\r\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fischglas für Euer Lager herstellen könnt. Mit diesem Schmuckstück könnt Ihr Euch selbst und anderen Abenteurern ein wenig Freude bereiten. Denn fröhliche Abenteurer sind starke Abenteurer und ich bin mir sicher, dass sich das auch in Euren Kampffähigkeiten niederschlagen wird.", objectives = "Sprecht mit Astaia in Darnassus, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "f1e19819d53833319b9230d299f7c16f9dbc785f1dedf1d081c84ab9e21b2cc4" }
quests[97946] = { title = "Grundlagen des Zeltens: Lederverarbeitung", description = "Ah, Ihr habt Euch also für Lederverarbeitung entschieden. Schön für Euch, $C. Ich glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Zelt anfertigt, das Euch an heißen Tagen Abkühlung verschafft und an Regentagen trocken hält.\r\n\r\nMit einem soliden Zelt über dem Kopf wird es Euch leichtfallen, alles andere zu bekommen, was Ihr braucht, um auf Euren Reisen immer auf Zack zu bleiben.", objectives = "Sprecht mit Nadyia Maneweaver auf der Straße von Dolanaar nach Darnassus, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "afd8672b899455361403bf369917811bb26c94a8bbeec7f197b10a7dbbbe98df" }
quests[97950] = { title = "Grundlagen des Zeltens: Schneiderei", description = "Die Schneiderei ist eine überraschend effektive Handwerkskunst, und ich bin sicher, sie wird Euch einigen Nutzen bringen.\r\n\r\nIch kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fraktionsbanner für Euer Lager anfertigt, sofern Ihr die Fertigkeit dazu habt. Motivation und Kampfmoral sind enorm wichtig für den Erfolg auf dem Schlachtfeld, und ein inspirierendes Banner sorgt dafür, dass Ihr mit vollem Einsatz bei der Sache bleibt.", objectives = "Sprecht mit Trianna in Darnassus, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "1044d2afe963397f8a052bc0690c8d555d387fc6131eb3519e7f7b5308f427b3" }
quests[98067] = { title = "Die Augen der Schildwache", description = "General Feathermoon achtet darauf, dass alle Wächter Zeit finden, zu Elune zu beten. Eine wahre Jägerin führt nicht allein die Klinge, sondern verlässt sich ebenso auf die Gaben der Göttin, um ihre Feinde zu besiegen.\r\n\r\nIhr könnt mich bei meinen täglichen Pflichten unterstützen. Platziert Wächtereulen in der Stadt: zunächst an den Tunneln, die im Norden in die Tiefen der Burg Cenarius führen, dann bei der Bank im Stadtzentrum, am Gasthaus auf der Terrasse der Handwerker im Nordosten und schließlich am Stadttor. Die Wachen werden Euch dabei behilflich sein.\r\n\r\nEtwas geht in Teldrassil vor sich... Wir müssen wachsam bleiben.", objectives = "Stellt für Schildwache Dalia Sunblade im Tempel des Mondes von Darnassus Wächtereulen am Eingang zu den Tiefen der Burg Cenarius, der Bank von Darnassus, dem Gasthaus auf der Terrasse der Handwerker und am Stadttor auf.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "a2899ec4599a317d4f5ea0d854d8d073b1e8b6ca0c25e44bd0940b5e932772ed" }
quests[98322] = { title = "Sichert den Pass", description = "In dunklen Höhlen herumzukraxeln ist was für Abenteurer. Ich schreib bloß die Berichte und schick sie nach Ironforge.\r\n\r\nJetzt ist es nur so, dass einer meiner Trupps vermisst wird, also nix mit Bericht! Ich hatte Gebirgsjäger losgeschickt, damit sie sich mal um das Wendigo-Problem da draußen kümmern, aber habe seitdem nichts von ihnen gehört.\r\n\r\nWenn Ihr sowieso unterwegs seid, schaut doch mal westlich von Kharanos nach Gebirgsjägerin Gretchen. Ich häng mit meinem Bericht hinterher!", objectives = "Seht westlich von Kharanos nach Gebirgsjägerin Gretchen.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "e86a2865e739e133943cc291d3109e442bf90ed14666b84b31f75d2a755baa11" }
quests[98391] = { title = "Die Schwesternschaft von Elune", description = "Seid gesegnet, $C. Die Schwesternschaft von Elune ist seit tausenden von Jahren eine standfeste Säule der Gesellschaft der Kaldorei.\r\n\r\nNoch vor der großen Teilung, noch vor dem Krieg der Ahnen und durch die lange Wacht hindurch haben wir unser Volk durch die Dunkelheit geführt und geheilt. Dies ist unsere Pflicht, dies ist der Anspruch der göttlichen Mondmutter.\r\n\r\nNun benötigen wir Eure Hilfe bei einer Sache allerhöchster Wichtigkeit. Schwester Aquinne harrt Eurer Ankunft in Darnassus.", objectives = "Sprecht mit Schwester Aquinne in Darnassus.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "f9f96908ff3d5d98119c50c4dbf29ff1e2ea896b53008f8e81ed011e01866083" }
quests[98403] = { title = "Krankhafter Hass", description = "Lord Melenas hat nicht allein gehandelt, sondern auf Geheiß eines Anderen. Xethorr der Verschlagene ist sein Name. Er hat offenbar die auf Teldrassil heimischen Spinnen verderbt, um ihr Gift für einen unheilvollen Plan zu missbrauchen.\r\n\r\nSein Domizil liegt nordwestlich von hier tief im Wald, in einer Gegend, die als die Kluft bekannt ist. Lasst Vorsicht walten und bringt Verbündete mit, denn Xethorr ist ein nicht zu unterschätzender Gegner.\r\n\r\nVernichtet seine Brut und bringt mir alles, das uns mehr über die Machenschaften des Satyrs verrät.", objectives = "Tötet $1oa besudelte Waldweber und bringt Tallonkai Swiftroot das ausgewachsene Teufelsmoos von Xethorr dem Verschlagenen.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "84cf5f7d1dfb6f08d17d7a3b73536a3516ff76ac94f2632cc026c75c9d6b0057" }
quests[99050] = { title = "Gaben des Großen Baums", description = "Ich brauche Eure Hilfe, um die Zutaten zu beschaffen, die ich benötige, um die Krankheit lange genug aufzuhalten, damit Eralya es bis hierher zurückschafft, um sich weiter behandeln zu lassen.\r\n\r\nGlücklicherweise ist unsere Heimat noch immer reich an Ressourcen und kann uns in Zeiten der Not versorgen.\r\n\r\nDie Hauptzutat sind taubedeckte Peitscherwedel. Ihr findet sie rund um den Al'Amethsee direkt südlich von hier oder am Wellspringsee und seinem Fluss im Nordwesten.\r\n\r\nZudem benötige ich eine leere Phiole und etwas Quellwasser. Beides kann man hier in der Stadt kaufen oder tauschen.", objectives = "Beschafft $1oa taubedeckte Peitscherwedel, eine leere Phiole und erfrischendes Quellwasser für Byancie in Dolanaar.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "eef60dba431fd45fd6930d83c799f04d0def555ced69e1858c28fe8577f56b1c" }
quests[99053] = { title = "Flucht aus Ban'ethil", description = "Meine Gebete wurden erhört! Ich bin Euch sehr dankbar, dass Ihr Euch den Weg hierher gebahnt habt.\r\n\r\nIch wurde vom Orakelbaum hierher gesandt, um den schlummernden Druiden hier eine Botschaft zu überbringen. Aber dieser Ort wurde komplett von Furbolgs überrannt! Sie haben mich überwältigt, bevor ich weglaufen konnte, und mich hierher gebracht. Ich fürchte, ich werde ihre nächste Mahlzeit sein.\r\n\r\nIch weiß nicht, wie es Euch geht, aber ich verabscheue diesen Ort. Unter der Erde haben die Kaldorei nichts zu suchen.", objectives = "Helft Schildwache Lynessa Duskblossom vom Grabhügel von Ban'ethil zu entkommen und berichtet dann Schildwache Kyra Starsong in Dolanaar, dass sie in Sicherheit ist.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "a9c7330a8415e9f5dd963cc29887d50b98274a102fd128a2d4371788227bb5a5" }
quests[99158] = { title = "Dämmerung in den Bergen", description = "Hier in den Bergen gibt es einen Priester, der einer Organisation namens Argentumdämmerung angehört. Es handelt sich bei ihnen um eine heilige Gruppe, die es sich zum Ziel gemacht hat, alles Unheilige und Unnatürliche zu vernichten.\r\n\r\nVater Gavin gehört allerdings eher zu jenen unter ihnen, der anderen hilft und Heilung anbietet, statt zur Waffe zu greifen. Er hat ein altes Gebäude hergerichtet, das nun als Rastort für Reisende dient. Ich habe eine Lieferung heiliger Kerzen für ihn. Könntet Ihr sie ihm bringen, wenn Ihr in die Richtung geht?", objectives = "Bringt die Kiste mit Kerzen zu Vater Gavin.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "7864dd80ac7ba56358c65dfd7bb8f8754a86bb5c6087bc7c8a575055a1856027" }
quests[99159] = { title = "Auf der Suche nach Wärme", description = "Mein Ofen steht jederzeit bereit, um allen frierenden Seele etwas Wärme zu spenden, doch ich würde Euch gerne um Hilfe bitten, wenn es Euch nichts ausmacht.\r\n\r\nIch brauche mehr Feuerholz. Normalerweise würde ich mich selbst darum kümmern, doch ich bin gerade anderweitig beschäftigt.", objectives = "Sammelt $1oa Stücke Feuerholz.", source = "native Forever deDE questcache.wdb build 70205", flavor = "forever", originFlavor = "forever", locale = "deDE", sourceBuild = 70205, sourceHash = "a067d4f2af691492f9c59ec5c280230891996d9175a7bfb40c8cdf13508d7cf4" }
